def _get_endpoint_context(
    endpoint: Callable[..., Any], path: str, method: Union[str, Sequence[str]]
) -> Optional[str]:
    try:
        file = inspect.getfile(endpoint)
        _, start_line = inspect.getsourcelines(endpoint)
        name = endpoint.__name__
        if isinstance(method, (list, set, tuple)):
            method_str = ", ".join(method)
        else:
            method_str = method
        return f"File {file}, line {start_line}, in {name} ({method_str} {path})"
    except Exception:
        return None


